import { useEffect,useMemo,useState } from "react"
import type { RouteConfig } from "@mercurjs/dashboard-sdk"
import { Actions,Button,Card,Empty,Field,FormGrid,Message,Page,PageHeader,Status } from "../../spike/ui"
import {Input} from "../../components/ui/input"
import {Textarea} from "../../components/ui/textarea"
import {Select} from "../../components/ui/select"
import {Table,TableBody,TableCell,TableHead,TableHeader,TableRow} from "../../components/ui/table"
declare const __BACKEND_URL__:string
export const config:RouteConfig={label:"منتجاتي",rank:18}
type P={id:string;title:string;description?:string;status?:string;thumbnail?:string;variants?:any[]};type Revision={id:string;product_id:string;status:string;rejection_reason?:string;changes?:Record<string,any>}
const api=async(path:string,init?:RequestInit)=>{const r=await fetch(`${__BACKEND_URL__}${path}`,{credentials:'include',...init,headers:{...(init?.body?{'content-type':'application/json'}:{}),...(init?.headers||{})}});const t=await r.text();let d:any={};try{d=t?JSON.parse(t):{}}catch{}if(!r.ok)throw new Error(d.message||t||`HTTP ${r.status}`);return d}
const statusText=(v?:string)=>{const s=String(v||'').toLowerCase();if(s==='pending'||s==='proposed')return 'بانتظار المراجعة';if(s==='published'||s==='approved')return 'منشور';if(s==='rejected')return 'مرفوض';if(s==='draft')return 'مسودة';return v||'—'};const tone=(v?:string):any=>{const s=String(v||'').toLowerCase();return ['published','approved'].includes(s)?'success':s==='rejected'?'danger':['pending','proposed'].includes(s)?'warning':'muted'}
export default function MyProducts(){const[products,setProducts]=useState<P[]>([]),[revisions,setRevisions]=useState<Revision[]>([]),[editing,setEditing]=useState<any>(null),[msg,setMsg]=useState(''),[query,setQuery]=useState(''),[filter,setFilter]=useState('all'),[loading,setLoading]=useState(true);const load=async()=>{setLoading(true);try{const[p,r]=await Promise.all([api('/vendor/products?limit=100&fields=id,title,description,status,thumbnail,*variants'),api('/vendor/spike/product-revisions')]);setProducts(p.products||[]);setRevisions(r.revisions||[])}finally{setLoading(false)}};useEffect(()=>{load().catch(e=>setMsg(e.message))},[]);const latest=useMemo(()=>{const m=new Map<string,Revision>();for(const r of revisions)if(!m.has(r.product_id))m.set(r.product_id,r);return m},[revisions]);const visible=products.filter(p=>{const q=query.trim().toLowerCase();if(q&&!p.title.toLowerCase().includes(q)&&!String(p.variants?.[0]?.sku||'').toLowerCase().includes(q))return false;if(filter==='all')return true;const r=latest.get(p.id),s=String(r?.status||p.status||'').toLowerCase();if(filter==='pending')return s.includes('pending')||p.status==='proposed';if(filter==='published')return ['published','approved'].includes(String(p.status||'').toLowerCase());if(filter==='rejected')return s==='rejected';return true});const start=(p:P)=>setEditing({product:p,title:p.title,description:p.description||'',price:''});const remove=async(p:P)=>{if(!confirm(`هل تريد حذف ${p.title}؟`))return;try{await api(`/vendor/spike/products/${p.id}`,{method:'DELETE'});setMsg('تم حذف المنتج');await load()}catch(e:any){setMsg(e.message)}};const save=async()=>{const p=editing.product;const offerId=p.variants?.find((v:any)=>v.offers?.length)?.offers?.[0]?.id||p.variants?.find((v:any)=>v.offer_id)?.offer_id||null;const changes:any={title:editing.title,description:editing.description};if(editing.price){changes.price=Number(editing.price);changes.currency='USD'}await api('/vendor/spike/product-revisions',{method:'POST',body:JSON.stringify({product_id:p.id,offer_id:offerId,product_title:p.title,changes})});setMsg('تم إرسال التعديل للإدارة للمراجعة.');setEditing(null);await load()};return <Page><PageHeader title="منتجاتي" description="إدارة منتجات متجرك والحالة والمخزون والتعديلات. التوصيل يحدده النظام تلقائيًا."/>{msg&&<Message>{msg}</Message>}<Card><FormGrid><Field label="بحث"><Input value={query} onChange={e=>setQuery(e.target.value)} placeholder="ابحث باسم المنتج أو SKU"/></Field><Field label="الحالة"><Select value={filter} onValueChange={setFilter} options={[{value:'all',label:'الكل'},{value:'published',label:'منشور'},{value:'pending',label:'بانتظار المراجعة'},{value:'rejected',label:'مرفوض'}]}/></Field></FormGrid></Card><Card>{loading?<Empty>جاري تحميل المنتجات...</Empty>:visible.length?<Table><TableHeader><TableRow><TableHead>المنتج</TableHead><TableHead>الحالة</TableHead><TableHead>SKU</TableHead><TableHead>المخزون</TableHead><TableHead>التوصيل</TableHead><TableHead>آخر تعديل</TableHead><TableHead>الإجراءات</TableHead></TableRow></TableHeader><TableBody>{visible.map(p=>{const rev=latest.get(p.id),stock=p.variants?.[0]?.inventory_quantity??p.variants?.[0]?.inventoryQuantity??'—';return <TableRow key={p.id}><TableCell><div className="flex items-center gap-3">{p.thumbnail?<img src={p.thumbnail} alt="" className="size-12 rounded-xl object-cover"/>:<div className="grid size-12 place-items-center rounded-xl bg-muted">SP</div>}<div><b>{p.title}</b><small className="block text-muted-foreground">{p.description||'بدون وصف'}</small></div></div></TableCell><TableCell><Status tone={tone(p.status)}>{statusText(p.status)}</Status></TableCell><TableCell><code>{p.variants?.[0]?.sku||'—'}</code></TableCell><TableCell>{stock}</TableCell><TableCell><Status tone="info">تلقائي حسب التغطية</Status></TableCell><TableCell>{rev?<div><Status tone={tone(rev.status)}>{statusText(rev.status)}</Status>{rev.status==='rejected'&&rev.rejection_reason?<small className="block text-muted-foreground">{rev.rejection_reason}</small>:null}</div>:<span className="text-muted-foreground">لا يوجد</span>}</TableCell><TableCell><Actions><Button tone="secondary" onClick={()=>start(p)}>تعديل</Button><Button tone="danger" onClick={()=>remove(p)}>حذف</Button></Actions></TableCell></TableRow>})}</TableBody></Table>:<Empty>لا توجد منتجات مطابقة</Empty>}</Card>{editing&&<div className="spike-modal-backdrop" onMouseDown={()=>setEditing(null)}><div className="spike-edit-modal" onMouseDown={e=>e.stopPropagation()}><PageHeader title="تعديل المنتج" description={editing.product.title}/><FormGrid><Field label="اسم المنتج"><Input value={editing.title} onChange={e=>setEditing({...editing,title:e.target.value})}/></Field><Field label="السعر الجديد بالدولار"><Input type="number" min="0" value={editing.price} onChange={e=>setEditing({...editing,price:e.target.value})} placeholder="اتركه فارغًا بدون تغيير"/></Field><Field label="الوصف" wide><Textarea rows={4} value={editing.description} onChange={e=>setEditing({...editing,description:e.target.value})}/></Field></FormGrid><Message>أي تعديل يتم إرساله للإدارة للمراجعة قبل اعتماده.</Message><Actions><Button onClick={save}>إرسال للموافقة</Button><Button tone="secondary" onClick={()=>setEditing(null)}>إلغاء</Button></Actions></div></div>}</Page>}
